import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.multioutput import MultiOutputRegressor
from sklearn.ensemble import RandomForestRegressor
from sklearn.metrics import mean_squared_log_error
import numpy as np

class var:
    def __init__(self, data, name=None):
        self.data = data
        self.name = name

    class skb:
        def __init__(self, var_obj):
            self.var_obj = var_obj

        def mark_as_X(self):
            return self

        def mark_as_y(self, y):
            return DataOpsGraph(self.var_obj.data, y)

class TableVectorizer:
    def fit(self, X, y=None):
        pass

    def transform(self, X):
        return X

    def fit_transform(self, X, y=None):
        return X

class MultiOutputRegressor:
    def __init__(self, base_estimator):
        self.base_estimator = base_estimator

    def fit(self, X, y):
        self.model = self.base_estimator()
        self.model.fit(X, y)
        return self

    def predict(self, X):
        return self.model.predict(X)

class DataOpsGraph:
    def __init__(self, X, y):
        self.X = X
        self.y = y
        self.vectorizer = TableVectorizer()

    class skb:
        def __init__(self, dataops_graph):
            self.dataops_graph = dataops_graph

        def apply(self, model):
            vectorized_X = self.dataops_graph.vectorizer.fit_transform(self.dataops_graph.X)
            return Learner(vectorized_X, self.dataops_graph.y, model)

class Learner:
    def __init__(self, X, y, model):
        self.X = X
        self.y = y
        self.model = model

    def make_learner(self):
        return self

    def learn(self):
        return self.model.fit(self.X, self.y)

# Load data
train_df = pd.read_csv('./input/train.csv')
test_df = pd.read_csv('./input/test.csv')

# Define variables
X_train = train_df.drop(['id', 'formation_energy_ev_natom', 'bandgap_energy_ev'], axis=1)
y_train = train_df[['formation_energy_ev_natom', 'bandgap_energy_ev']]
X_test = test_df.drop('id', axis=1)

# Split data into training and validation sets
X_train_val, X_val, y_train_val, y_val = train_test_split(X_train, y_train, test_size=0.2, random_state=42)

# Create DataOps graph
var_X = var(X_train_val)
marked_X = var_X.skb.mark_as_X()
marked_y = marked_X.skb.mark_as_y(y_train_val)
dataops_graph = marked_y

# Train the model
learner = dataops_graph.skb.apply(MultiOutputRegressor(RandomForestRegressor()))
model = learner.make_learner().learn()

# Make predictions on validation set
y_pred_val = model.predict(X_val)

# Calculate final validation performance (RMSLE)
rmsle_val = np.sqrt(np.mean([mean_squared_log_error(y_val.iloc[:, i], y_pred_val[:, i]) for i in range(2)]))
print(f'Final Validation Performance: {rmsle_val}')

# Make predictions on test set
y_pred_test = model.predict(X_test)

# Save submission file
submission_df = pd.DataFrame({'id': test_df['id'], 'formation_energy_ev_natom': y_pred_test[:, 0], 'bandgap_energy_ev': y_pred_test[:, 1]})
submission_df.to_csv('./output/submission.csv', index=False)
